class MiddlewareManager {
  constructor () {
    this.middleware = [];

    this.call = this.call.bind (this);
    this.wrapWithMiddleware = this.wrapWithMiddleware.bind (this);
  }

  call({methodName, stage = 'pre', params}) {}

  wrapWithMiddleware({method, methodName}) {
    const call = this.call;
    return function (...args) {
      call ({
        methodName,
        stage: 'pre',
        params: null,
      });
      const methodReturn = method (...args);
      call ({
        methodName,
        stage: 'post',
        params: {methodReturn},
      });
      return methodReturn;
    };
  }
}

module.exports = MiddlewareManager;
